script:
frappe.ui.form.on('Customer', {
    refresh: function(frm) {
        // Construction du HTML qui contient le conteneur pour le tableau et le bouton sous le tableau
        let html_content = `
            <div id="title" style="margin-top: 5px; font-size: 14px;">Liste Contacts</div>
            <div id="contacts-table" style="margin-top: 10px;"></div>
            <button class="btn btn-secondary btn-xs" id="add-contact-btn" style="margin-top: 10px; margin-bottom: 10px;">Ajouter Contact</button>
        `;
        frm.get_field('custom_contact_html_custom').$wrapper.html(html_content);

        // Fonction pour charger et afficher la liste des contacts via la méthode Python
        function load_contacts() {
            frappe.call({
                method: "log.log.customer_hooks.get_customer_contacts", // Vérifiez le chemin de votre méthode
                args: { customer: frm.doc.name },
                callback: function(r) {
                    if (r.message) {
                        let data = r.message;
                        // Construction du tableau HTML avec attribution d'un data-docname pour chaque ligne
                        let table_html = `<table id="contacts-table-inner">
                            <thead>
                                <tr>
                                    <th>Contact</th>
                                    <th>Fonction</th>
                                    <th>Mobile</th>
                                    <th>Email</th>
                                </tr>
                            </thead>
                            <tbody>`;
                        data.forEach(function(contact) {
                            table_html += `<tr class="contact-row" data-docname="${contact.docname}">
                                <td><strong>${contact.contact}</strong></td>
                                <td>${contact.designation}</td>
                                <td>${contact.mobile}</td>
                                <td>${contact.email}</td>
                            </tr>`;
                        });
                        table_html += `</tbody></table>`;
                        frm.get_field('custom_contact_html_custom').$wrapper.find('#contacts-table').html(table_html);

                        // Injection du CSS pour le style du tableau
                        let css = `
                         <style>
                        /* Conteneur du tableau */
                        #contacts-table {
                            overflow-x: auto;
                        }
                        /* Style du tableau */
                        #contacts-table-inner {
                            border-collapse: separate;
                            border-spacing: 0;
                            width: 100%;
                            border: 0.4px solid #e9ecef;
                            border-radius: 8px;
                            overflow: hidden;
                            font-size: 12px;
                        }
                        #contacts-table-inner th {
                            background-color: #f2f2f2;
                            border: 0.4px solid #e9ecef;
                            padding: 8px;
                            white-space: nowrap;
                        }
                        #contacts-table-inner td {
                            border: 0.4px solid #e9ecef;
                            padding: 8px;
                            white-space: nowrap;
                        }
                        #contacts-table-inner thead tr:first-child th:first-child {
                            border-top-left-radius: 8px;
                        }
                        #contacts-table-inner thead tr:first-child th:last-child {
                            border-top-right-radius: 8px;
                        }
                        #contacts-table-inner tbody tr:last-child td:first-child {
                            border-bottom-left-radius: 8px;
                        }
                        #contacts-table-inner tbody tr:last-child td:last-child {
                            border-bottom-right-radius: 8px;
                        }
                        /* Curseur pointer sur la ligne */
                        #contacts-table-inner tbody tr.contact-row {
                            cursor: pointer;
                        }
                        </style>
                        `;
                        // On ajoute le style dans le wrapper (s'il n'est pas déjà présent)
                        if (frm.get_field('custom_contact_html_custom').$wrapper.find('style').length === 0) {
                            frm.get_field('custom_contact_html_custom').$wrapper.append(css);
                        }

                        // Ajout d'un événement click sur chaque ligne du tableau
                        frm.get_field('custom_contact_html_custom').$wrapper.find('#contacts-table-inner tbody')
                            .on('click', 'tr.contact-row', function() {
                                let docname = $(this).attr('data-docname');
                                // Utilisation de frappe.set_route pour naviguer vers le formulaire Contact
                                frappe.set_route("Form", "Contact", docname);
                            });
                    }
                }
            });
        }

        // Chargement initial des contacts
        load_contacts();

        // Gestion du clic sur le bouton pour ajouter un contact
        frm.get_field('custom_contact_html_custom').$wrapper.find('#add-contact-btn').click(function() {
            frappe.prompt([
                {
                    "fieldname": "first_name",
                    "fieldtype": "Data",
                    "label": __("First Name"),
                    "reqd": 1
                },
                {
                    "fieldname": "last_name",
                    "fieldtype": "Data",
                    "label": __("Last Name"),
                    "reqd": 1
                },
                {
                    "fieldname": "designation",
                    "fieldtype": "Data",
                    "label": __("Fonction"),
                    "reqd": 1
                },
                {
                    "fieldname": "mobile_no",
                    "fieldtype": "Data",
                    "label": __("Téléphone Mobile"),
                    "reqd": 1
                },
                {
                    "fieldname": "email",
                    "fieldtype": "Data",
                    "label": __("Email"),
                    "reqd": 1
                },
                {
                    "fieldname": "is_primary",
                    "fieldtype": "Check",
                    "label": __("Est Contact Principal"),
                    "default": 0
                }
            ],
            function(values) {
                frappe.call({
                    method: "frappe.client.insert",
                    args: {
                        doc: {
                            doctype: "Contact",
                            first_name: values.first_name,
                            last_name: values.last_name,
                            designation: values.designation,
                            is_primary_contact: 1,
                            links: [{
                                link_doctype: "Customer",
                                link_name: frm.doc.name
                            }],
                            phone_nos: [{
                                phone: values.mobile_no,
                                is_primary_mobile_no: 1
                            }],
                            email_ids: [{
                                email_id: values.email,
                                is_primary: 1
                            }]
                        }
                    },
                    callback: function(r) {
                        if (r.message) {
                            frappe.msgprint("Contact ajouté avec succès");
                            if (values.is_primary) {
                                frappe.call({
                                    method: "frappe.client.set_value",
                                    args: {
                                        doctype: "Customer",
                                        name: frm.doc.name,
                                        fieldname: "customer_primary_contact",
                                        value: r.message.name
                                    },
                                    callback: function() {
                                        frappe.msgprint("Customer mis à jour avec le contact principal");
                                    }
                                });
                            }
                            // Recharge le tableau des contacts après insertion
                            load_contacts();
                        }
                    }
                });
            },
            __("Ajouter un Contact"),
            __("Créer")
            );
        });
    }
});
